import Link from "next/link";
import { notFound } from "next/navigation";
import { marked } from "marked";
import { getReport } from "@/lib/report";

export const dynamic = "force-dynamic";

export default async function ReportPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const rep = await getReport(id);
  if (!rep) notFound();
  // Report markdown is generated by our own code from NASA data; strip any raw HTML just in case.
  const html = await marked.parse(rep.markdown.replace(/</g, "&lt;"), { gfm: true });
  return (
    <main className="container" style={{ maxWidth: 980 }}>
      <div className="row" style={{ justifyContent: "space-between", marginBottom: 12 }}>
        <Link href="/reports" className="small">← All reports</Link>
        <div className="row">
          {rep.caseId && <Link className="btn" href={`/case/${rep.caseId}`}>Open agent room</Link>}
          <a className="btn" href={`/api/reports/${rep.id}?format=md`}>Download .md</a>
        </div>
      </div>
      <article className="card markdown" dangerouslySetInnerHTML={{ __html: html }} />
    </main>
  );
}
